import{Base}from"../primitives/Base.js";class Display extends Base{onblamready(){this.elem=document.querySelector(this.from)||this.parentNode,this.render(),this.watchProps([this.elem],_=>this.render(),[this.prop])}render(){let value=this.elem[this.prop];this.textContent=isNaN(value)?value:parseFloat(value).toFixed(this.places)}get from(){return this.getAttribute("from")}set from(value){this.setAttribute("from",value)}get prop(){return this.getAttribute("prop")}set prop(value){this.setAttribute("prop",value)}get places(){let value=this.getAttribute("places");return value?parseFloat(value):0}set places(value){this.setAttribute("places",value)}}export{Display};